  }

  public static Node paramList(Node ... params) {
    Node result = paramList();
    for (int i = 0; i < params.length; i++) {
      Preconditions.checkState(params[i].isName());
      result.addChildToBack(params[i]);
    }
    return result;
  }

  public static Node paramList(List<Node> params) {
    Node result = paramList();
    for (int i = 0; i < params.size(); i++) {
      Node current = params.get(i);
      Preconditions.checkState(current.isName());
      result.addChildToBack(current);
    }
    return result;
  }

  public static Node block() {
    return new Node(Token.BLOCK);
  }

  public static Node block(Node stmt) {
    Preconditions.checkState(mayBeStatement(stmt));
    return new Node(Token.BLOCK, stmt);
  }

  public static Node block(Node ... stmts) {
    Node result = new Node(Token.BLOCK);
    for (int i = 0; i < stmts.length; i++) {
      Preconditions.checkState(mayBeStatement(stmts[i]));
      result.addChildToBack(stmts[i]);
    }
    return result;
  }


  public static Node script(Node ... stmts) {
    // TODO(johnlenz): finish setting up the SCRIPT node
