package com.google.javascript.rhino;

import com.google.common.base.Preconditions;

import java.util.List;

/**
 * An AST construction helper class
 * @author johnlenz@google.com (John Lenz)
 */
public class IR {

  private IR() {}

  public static Node empty() {
    return new Node(Token.EMPTY);
  }

  public static Node function(Node fnName, Node fnParams, Node fnBody) {
    Preconditions.checkState(fnName.isName());
    Preconditions.checkState(fnParams.isParamList());
    Preconditions.checkState(fnBody.isBlock());
    return new Node(Token.FUNCTION, fnName, fnParams, fnBody);
  }

  public static Node paramList() {
    return new Node(Token.PARAM_LIST);
  }

  public static Node paramList(Node param) {
    Preconditions.checkState(param.isName());
    return new Node(Token.PARAM_LIST, param);
  }

  public static Node paramList(Node ... params) {
    Node result = paramList();
    for (int i = 0; i < params.length; i++) {
      Node param = params[i];
      Preconditions.checkState(param.isName());
      result.addChildToBack(param);
    }
    return result;
  }

  public static Node paramList(List<Node> params) {
    Node result = paramList();
    for (int i = 0; i < params.size(); i++) {
      Node param = params.get(i);
      Preconditions.checkState(param.isName());
      result.addChildToBack(param);
    }
    return result;
  }

  public static Node block() {
    return new Node(Token.BLOCK);
  }

  public static Node block(Node stmt) {
    Preconditions.checkState(mayBeStatement(stmt));
    return new Node(Token.BLOCK, stmt);
  }

  public static Node block(Node ... stmts) {
    Node result = new Node(Token.BLOCK);
    for (int i = 0; i < stmts.length; i++) {
      Node stmt = stmts[i];
      Preconditions.checkState(mayBeStatement(stmt));
      result.addChildToBack(stmt);
    }
    return result;
  }


  public static Node script(Node ... stmts) {
    // TODO(johnlenz): finish setting up the SCRIPT node
    Node result = new Node(Token.SCRIPT);
    for (int i = 0; i < stmts.length; i++) {
      Node stmt = stmts[i];
      Preconditions.checkState(mayBeStatement(stmt));
      result.addChildToBack(stmt);
    }
    return result;
  }

  public static Node var(Node varName, Node initValue) {
    Preconditions.checkState(varName.isName() && !varName.hasChildren());
    Preconditions.checkState(mayBeExpression(initValue));
    varName.addChildToFront(initValue);
    return var(varName);
  }

  public static Node var(Node varName) {
    Preconditions.checkState(varName.isName());
    return new Node(Token.VAR, varName);
  }

  public static Node returnNode() {
    return new Node(Token.RETURN);
  }

  public static Node returnNode(Node value) {
    Preconditions.checkState(mayBeExpression(value));
    return new Node(Token.RETURN, value);
  }

  public static Node throwNode(Node value) {
    Preconditions.checkState(mayBeExpression(value));
    return new Node(Token.THROW, value);
  }

  public static Node exprResult(Node value) {
    Preconditions.checkState(mayBeExpression(value));
    return new Node(Token.EXPR_RESULT, value);
  }

  public static Node ifNode(Node test, Node thenBlock) {
    Preconditions.checkState(mayBeExpression(test));
    Preconditions.checkState(thenBlock.isBlock());
    return new Node(Token.IF, test, thenBlock);
  }

  public static Node ifNode(Node test, Node thenBlock, Node otherwise) {
    Preconditions.checkState(mayBeExpression(test));
    Preconditions.checkState(thenBlock.isBlock());
    Preconditions.checkState(otherwise.isBlock());
    return new Node(Token.IF, test, thenBlock, otherwise);
  }

  public static Node doNode(Node loopBody, Node test) {
    Preconditions.checkState(loopBody.isBlock());
    Preconditions.checkState(mayBeExpression(test));
    return new Node(Token.DO, loopBody, test);
  }

  public static Node forIn(Node lhs, Node rhs, Node loopBody) {
    Preconditions.checkState(lhs.isVar() || mayBeExpression(lhs));
    Preconditions.checkState(mayBeExpression(rhs));
    Preconditions.checkState(loopBody.isBlock());
    return new Node(Token.FOR, lhs, rhs, loopBody);
  }

  public static Node forNode(Node initializer, Node test, Node update, Node loopBody) {
    Preconditions.checkState(initializer.isVar() || mayBeExpressionOrEmpty(initializer));
    Preconditions.checkState(mayBeExpressionOrEmpty(test));
    Preconditions.checkState(mayBeExpressionOrEmpty(update));
    Preconditions.checkState(loopBody.isBlock());
    return new Node(Token.FOR, initializer, test, update, loopBody);
  }

  public static Node switchNode(Node discriminant, Node ... cases) {
    Preconditions.checkState(mayBeExpression(discriminant));
    Node result = new Node(Token.SWITCH, discriminant);
    for (int i = 0; i < cases.length; i++) {
      Node c = cases[i];
      Preconditions.checkState(c.isCase() || c.isDefaultCase());
      result.addChildToBack(c);
    }
    return result;
  }

  public static Node caseNode(Node value, Node caseBody) {
    Preconditions.checkState(mayBeExpression(value));
    Preconditions.checkState(caseBody.isBlock());
    caseBody.putBooleanProp(Node.SYNTHETIC_BLOCK_PROP, true);
    return new Node(Token.CASE, value, caseBody);
  }

  public static Node defaultCase(Node caseBody) {
    Preconditions.checkState(caseBody.isBlock());
    caseBody.putBooleanProp(Node.SYNTHETIC_BLOCK_PROP, true);
    return new Node(Token.DEFAULT_CASE, caseBody);
  }

  public static Node label(Node labelNameNode, Node stmt) {
    // TODO(johnlenz): additional validation here.
    Preconditions.checkState(labelNameNode.isLabelName());
    Preconditions.checkState(mayBeStatement(stmt));
    return new Node(Token.LABEL, labelNameNode, stmt);
  }

  public static Node labelName(String text) {
    Preconditions.checkState(!text.isEmpty());
    return Node.newString(Token.LABEL_NAME, text);
  }

  public static Node tryFinally(Node tryBlock, Node finallyBlock) {
    Preconditions.checkState(tryBlock.isLabelName());
    Preconditions.checkState(finallyBlock.isLabelName());
    Node emptyCatch = block().copyInformationFrom(tryBlock);
    return new Node(Token.TRY, tryBlock, emptyCatch, finallyBlock);
  }

  public static Node tryCatch(Node tryBlock, Node catchClause) {
    Preconditions.checkState(tryBlock.isBlock());
    Preconditions.checkState(catchClause.isCatch());
    Node catchWrapper = block(catchClause).copyInformationFrom(catchClause);
    return new Node(Token.TRY, tryBlock, catchWrapper);
  }

  public static Node tryCatchFinally(
      Node tryBlock, Node catchClause, Node finallyBlock) {
    Preconditions.checkState(finallyBlock.isBlock());
    Node result = tryCatch(tryBlock, catchClause);
    result.addChildToBack(finallyBlock);
    return result;
  }

  public static Node catchNode(Node param, Node catchBody) {
    Preconditions.checkState(param.isName());
    Preconditions.checkState(catchBody.isBlock());
    return new Node(Token.CATCH, param, catchBody);
  }

  public static Node breakNode() {
    return new Node(Token.BREAK);
  }

  public static Node breakNode(Node label) {
    // TODO(johnlenz): additional validation here.
    Preconditions.checkState(label.isLabelName());
    return new Node(Token.BREAK, label);
  }

  public static Node continueNode() {
    return new Node(Token.CONTINUE);
  }

  public static Node continueNode(Node label) {
    // TODO(johnlenz): additional validation here.
    Preconditions.checkState(label.isLabelName());
    return new Node(Token.CONTINUE, label);
  }


  //

  public static Node call(Node callee, Node ... args) {
    Node result = new Node(Token.CALL, callee);
    for (int i = 0; i < args.length; i++) {
      Node arg = args[i];
      Preconditions.checkState(mayBeExpression(arg));
      result.addChildToBack(arg);
    }
    return result;
  }

  public static Node newNode(Node callee, Node ... args) {
    Node result = new Node(Token.NEW, callee);
    for (int i = 0; i < args.length; i++) {
      Node arg = args[i];
      Preconditions.checkState(mayBeExpression(arg));
      result.addChildToBack(arg);
    }
    return result;
  }

  public static Node name(String identifier) {
    return Node.newString(Token.NAME, identifier);
  }

  public static Node getprop(Node object, Node property) {
    Preconditions.checkState(mayBeExpression(object));
    Preconditions.checkState(property.isString());
    return new Node(Token.GETPROP, object, property);
  }

  public static Node getelem(Node object, Node index) {
    Preconditions.checkState(mayBeExpression(object));
    Preconditions.checkState(mayBeExpression(index));
    return new Node(Token.GETELEM, object, index);
  }

  public static Node assign(Node lhs, Node rhs) {
    Preconditions.checkState(isAssignmentTarget(lhs));
    Preconditions.checkState(mayBeExpression(rhs));
    return new Node(Token.ASSIGN, lhs, rhs);
  }

  public static Node hook(Node test, Node whenTrue, Node whenFalse) {
    Preconditions.checkState(mayBeExpression(test));
    Preconditions.checkState(mayBeExpression(whenTrue));
    Preconditions.checkState(mayBeExpression(whenFalse));
    return new Node(Token.HOOK, test, whenTrue, whenFalse);
  }

  public static Node comma(Node left, Node right) {
    return binaryOp(Token.COMMA, left, right);
  }

  public static Node and(Node left, Node right) {
    return binaryOp(Token.AND, left, right);
  }

  public static Node or(Node left, Node right) {
    return binaryOp(Token.OR, left, right);
  }

  public static Node not(Node operand) {
    return unaryOp(Token.NOT, operand);
  }

  /**
   * "=="
   */
  public static Node eq(Node left, Node right) {
    return binaryOp(Token.EQ, left, right);
  }

  /**
   * "==="
   */
  public static Node sheq(Node left, Node right) {
    return binaryOp(Token.SHEQ, left, right);
  }

  public static Node voidNode(Node operand) {
    return unaryOp(Token.VOID, operand);
  }

  public static Node neg(Node operand) {
    return unaryOp(Token.NEG, operand);
  }

  public static Node pos(Node operand) {
    return unaryOp(Token.POS, operand);
  }

  public static Node add(Node left, Node right) {
    return binaryOp(Token.ADD, left, right);
  }

  public static Node sub(Node left, Node right) {
    return binaryOp(Token.SUB, left, right);
  }

  // TODO(johnlenz): the rest of the ops

  // literals
  public static Node objectlit(Node ... propdefs) {
    Node result = new Node(Token.OBJECTLIT);
    for (int i = 0; i < propdefs.length; i++) {
      Node propdef = propdefs[i];
      Preconditions.checkState(
          propdef.isStringKey() ||
          propdef.isGetterDef() || propdef.isSetterDef());
      Preconditions.checkState(propdef.hasOneChild());
      result.addChildToBack(propdef);
    }
    return result;
  }

  // TODO(johnlenz): quoted props

  public static Node propdef(Node key, Node value) {
    Preconditions.checkState(key.isStringKey());
    Preconditions.checkState(!key.hasChildren());
    Preconditions.checkState(mayBeExpression(value));
    key.addChildToFront(value);
    return key;
  }

  public static Node arraylit(Node ... exprs) {
    Node result = new Node(Token.ARRAYLIT);
    for (int i = 0; i < exprs.length; i++) {
      Node element = exprs[i];
      Preconditions.checkState(mayBeExpressionOrEmpty(element));
      result.addChildToBack(element);
    }
    return result;
  }

  public static Node regexp(Node pattern) {
    Preconditions.checkState(pattern.isString());
    return new Node(Token.REGEXP, pattern);
  }

  public static Node regexp(Node pattern, Node modifiers) {
    Preconditions.checkState(pattern.isString());
    Preconditions.checkState(modifiers.isString());
    return new Node(Token.REGEXP, pattern, modifiers);
  }

  public static Node string(String value) {
    return Node.newString(value);
  }

  public static Node stringKey(String value) {
    return Node.newString(Token.STRING_KEY, value);
  }

  public static Node number(double value) {
    return Node.newNumber(value);
  }

  public static Node thisNode() {
    return new Node(Token.THIS);
  }

  public static Node trueNode() {
    return new Node(Token.TRUE);
  }

  public static Node falseNode() {
    return new Node(Token.FALSE);
  }

  public static Node nullNode() {
    return new Node(Token.NULL);
  }

  // helper methods

  private static Node binaryOp(int token, Node left, Node right) {
    Preconditions.checkState(mayBeExpression(left));
    Preconditions.checkState(mayBeExpression(right));
    return new Node(token, left, right);
  }

  private static Node unaryOp(int token, Node operand) {
    Preconditions.checkState(mayBeExpression(operand));
    return new Node(token, operand);
  }

  private static boolean mayBeExpressionOrEmpty(Node n) {
    return mayBeExpression(n) || n.isEmpty();
  }

  private static boolean isAssignmentTarget(Node n) {
    return n.isGetElem() || n.isGetProp() || n.isName();
  }

  // NOTE: some nodes are neither statements nor expression nodes:
  //   SCRIPT, LABEL_NAME, PARAM_LIST, CASE, DEFAULT_CASE, CATCH
  //   GETTER_DEF, SETTER_DEF

  /**
   * It isn't possible to always determine if a detached node is a expression,
   * so make a best guess.
   */
  private static boolean mayBeStatement(Node n) {
    switch (n.getType()) {
      case Token.EMPTY:
      case Token.FUNCTION:
        // EMPTY and FUNCTION are used both in expression and statement
        // contexts
        return true;

      case Token.BLOCK:
      case Token.BREAK:
      case Token.CONST:
      case Token.CONTINUE:
      case Token.DEBUGGER:
      case Token.DO:
      case Token.EXPR_RESULT:
      case Token.FOR:
      case Token.IF:
      case Token.LABEL:
      case Token.RETURN:
      case Token.SWITCH:
      case Token.THROW:
      case Token.TRY:
      case Token.VAR:
      case Token.WHILE:
      case Token.WITH:
        return true;

      default:
        return false;
    }
  }

  /**
   * It isn't possible to always determine if a detached node is a expression,
   * so make a best guess.
   */
  private static boolean mayBeExpression(Node n) {
    switch (n.getType()) {
      case Token.FUNCTION:
        // FUNCTION is used both in expression and statement
        // contexts.
        return true;

      case Token.ADD:
      case Token.AND:
      case Token.ARRAYLIT:
      case Token.ASSIGN:
      case Token.ASSIGN_BITOR:
      case Token.ASSIGN_BITXOR:
      case Token.ASSIGN_BITAND:
      case Token.ASSIGN_LSH:
      case Token.ASSIGN_RSH:
      case Token.ASSIGN_URSH:
      case Token.ASSIGN_ADD:
      case Token.ASSIGN_SUB:
      case Token.ASSIGN_MUL:
      case Token.ASSIGN_DIV:
      case Token.ASSIGN_MOD:
      case Token.BITAND:
      case Token.BITOR:
      case Token.BITNOT:
      case Token.BITXOR:
      case Token.CALL:
      case Token.COMMA:
      case Token.DEC:
      case Token.DELPROP:
      case Token.DIV:
      case Token.EQ:
      case Token.FALSE:
      case Token.GE:
      case Token.GETPROP:
      case Token.GETELEM:
      case Token.GT:
      case Token.HOOK:
      case Token.IN:
      case Token.INC:
      case Token.INSTANCEOF:
      case Token.LE:
      case Token.LSH:
      case Token.LT:
      case Token.MOD:
      case Token.MUL:
      case Token.NAME:
      case Token.NE:
      case Token.NEG:
      case Token.NEW:
      case Token.NOT:
      case Token.NUMBER:
      case Token.NULL:
      case Token.OBJECTLIT:
      case Token.OR:
      case Token.POS:
      case Token.REGEXP:
      case Token.RSH:
      case Token.SHEQ:
      case Token.SHNE:
      case Token.STRING:
      case Token.SUB:
      case Token.THIS:
      case Token.TYPEOF:
      case Token.TRUE:
      case Token.URSH:
      case Token.VOID:
        return true;

      default:
        return false;
    }
  }
}

